turns.verify:
f={D}/settle.csv; test -f $f || { echo FAIL: no settle.csv; exit 0; }
sed 's/^/SHOW /' $f | head -10
python3 - {D}/expenses.csv "$f" <<'EOF'
import csv, sys
net = {}
for r in csv.DictReader(open(sys.argv[1])):
    people = r["split_between"].split(";")
    amt = float(r["amount"])
    net[r["paid_by"]] = net.get(r["paid_by"], 0) + amt
    for p in people:
        net[p] = net.get(p, 0) - amt / len(people)
rows = list(csv.DictReader(open(sys.argv[2])))
hdr = rows and set(k.strip().lower() for k in rows[0].keys()) >= {"from", "to", "amount"}
if not hdr:
    print("FAIL: header is not from,to,amount"); sys.exit()
for r in rows:
    r = {k.strip().lower(): (v or "").strip() for k, v in r.items()}
    a = float(r["amount"].lstrip("$"))
    if a <= 0:
        print(f"FAIL: non-positive amount {a}"); sys.exit()
    net[r["from"]] = net.get(r["from"], 0) + a
    net[r["to"]] = net.get(r["to"], 0) - a
left = {k: round(v, 3) for k, v in net.items() if abs(v) > 0.02}
print(f"SHOW payments={len(rows)} unsettled={left}")
print("PASS" if not left and len(rows) <= 3 else f"FAIL: payments={len(rows)} unsettled={left}")
EOF
